// Step 2: Normalize a Telegram update into the unified payload used by the rest of the workflow.
// Content precedence (do not reorder): photo > sticker > voice/audio > location > animation > document > video > contact > text > empty
const MAX_TEXT_LENGTH = 3000;

function logEvent(event, details = {}) {
  console.log(JSON.stringify({ event, ...details, timestamp: new Date().toISOString() }));
}
// All Telegram send nodes use parse_mode = HTML, so any user-controlled text placed in a reply
// must have & < > escaped. (n8n's default is Markdown, where a single _ or * breaks the message.)
const escapeHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toInt = (value) => (value != null ? Number.parseInt(value, 10) : null);
const results = [];

for (const item of $input.all()) {
  try {
    const raw = item?.json;
    if (!raw || typeof raw !== 'object') {
      logEvent('invalid_payload', { reason: 'Malformed payload' });
      results.push({ json: { valid: false, error_reason: 'Malformed payload' } });
      continue;
    }

    const isEdited = !!raw.edited_message;
    const message = raw.message || raw.edited_message;
    if (!message || typeof message !== 'object') {
      logEvent('invalid_payload', { reason: 'Unknown update type', update_id: raw.update_id ?? null });
      results.push({ json: { valid: false, error_reason: 'Unknown update type' } });
      continue;
    }

    const fromUser = message.from || {};
    const chat = message.chat || {};
    const languageCode = typeof fromUser.language_code === 'string' ? fromUser.language_code.toLowerCase() : null;

    const normalized = {
      event_type: isEdited ? 'edited_message' : 'message',
      update_id: toInt(raw.update_id),
      chat_id: toInt(chat.id), // private chats only, so chat_id = user_id
      chat_type: chat.type ?? null,
      // escaped for HTML replies (welcome / unsupported)
      user_name: escapeHtml([fromUser.first_name, fromUser.last_name].filter(Boolean).join(' ') || fromUser.username || 'Anonymous'),
      // Telegram app language. Used only for replies sent before we read the message text.
      ui_lang: languageCode && languageCode.startsWith('ar') ? 'ar' : 'en',
      content_type: 'unknown',
      media_type: null,
      text: null,
      valid: true,
      error_reason: null,
    };

    const missingField = ['update_id', 'chat_id'].find((key) => !Number.isInteger(normalized[key]));
    if (missingField) {
      normalized.valid = false;
      normalized.error_reason = `Missing ${missingField}`;
      logEvent('missing_identity', { reason: normalized.error_reason, update_id: normalized.update_id });
      results.push({ json: normalized });
      continue;
    }

    // This bot is for 1:1 support. In groups chat_id != user_id and many users would share one history.
    if (chat.type !== 'private') {
      normalized.valid = false;
      normalized.error_reason = 'Non-private chat';
      logEvent('non_private_chat', { update_id: normalized.update_id, chat_type: chat.type ?? null });
      results.push({ json: normalized });
      continue;
    }

    const rawText = typeof message.text === 'string'
      ? message.text
      : (typeof message.caption === 'string' ? message.caption : '');
    const cleanText = rawText.trim();

    // Over-limit text stays invalid but is classified as unsupported so the user still gets a reply.
    if (cleanText.length > MAX_TEXT_LENGTH) {
      normalized.valid = false;
      normalized.content_type = 'unsupported';
      normalized.media_type = 'text_too_long';
      normalized.error_reason = `Text exceeds ${MAX_TEXT_LENGTH} characters limit`;
      logEvent('unsupported_input', { reason: normalized.error_reason, update_id: normalized.update_id });
      results.push({ json: normalized });
      continue;
    }

    if (Array.isArray(message.photo) && message.photo.length) {
      normalized.content_type = 'photo';
    } else if (message.sticker) {
      normalized.content_type = 'unsupported';
      normalized.media_type = 'sticker';
    } else if (message.voice || message.audio) {
      normalized.content_type = 'audio';
    } else if (message.location) {
      normalized.content_type = 'unsupported';
      normalized.media_type = 'location';
    } else if (message.animation) {
      normalized.content_type = 'unsupported';
      normalized.media_type = 'animation';
    } else if (message.document) {
      normalized.content_type = 'document';
    } else if (message.video) {
      normalized.content_type = 'video';
    } else if (message.contact) {
      normalized.content_type = 'unsupported';
      normalized.media_type = 'contact';
    } else if (cleanText) {
      normalized.content_type = 'text';
      normalized.text = cleanText; // raw text (not escaped): saved to DB and sent to the AI
    } else {
      normalized.content_type = 'empty';
    }

    logEvent('message_normalized', {
      update_id: normalized.update_id,
      content_type: normalized.content_type,
      event_type: normalized.event_type,
    });
    results.push({ json: normalized });
  } catch (error) {
    logEvent('processing_error', { error: error?.message || String(error) });
    results.push({ json: { valid: false, error_reason: 'Processing error' } });
  }
}

return results;

// Builds:
// 1) prompt         -> HR Agent (today's date + full history)
// 2) route_decision -> set HERE (no LLM call) for pure greetings/thanks, to save the free daily quota

const msg = $('Normalize Message').first().json;
const history = Array.isArray($json.history) ? $json.history : [];
const now = DateTime.now().setZone('Africa/Cairo');
const today = `${now.toFormat('yyyy-MM-dd')} (${now.setLocale('en').toFormat('cccc')})`;

const turns = history.map((h) => {
  const answer = h.response_text ? h.response_text : '[still being answered separately - do not answer it again]';
  return `User: ${h.text}\nAssistant: ${answer}`;
});
const prompt = [
  `Today is ${today}, Cairo time. Weekend: Friday and Saturday.`,
  '',
  'Conversation so far (oldest first):',
  turns.length ? turns.join('\n---\n') : '(this is the first message)',
  '',
  'Current message (answer this one):',
  '<<<',
  msg.text,
  '>>>',
].join('\n');

// ---- no-LLM fast route: a message made ONLY of greeting/thanks words (max 6 words) ----
// "تمام" / "ok" are NOT here on purpose: they can be a confirmation of a pending request.
const GREET = new Set(['السلام', 'عليكم', 'ورحمة', 'الله', 'وبركاته', 'سلام', 'صباح', 'مساء', 'الخير', 'النور', 'الفل',
  'اهلا', 'أهلا', 'اهلاً', 'أهلاً', 'هلا', 'هاي', 'hi', 'hello', 'hey', 'شكرا', 'شكراً', 'متشكر', 'متشكرين', 'تسلم',
  'تسلمي', 'ميرسي', 'thanks', 'thank', 'you', 'thx', 'يا', 'نور', 'جزيلا', 'جزيلاً', 'كتير', 'خالص']);
const words = String(msg.text || '').toLowerCase().replace(/[^\p{L}\s]/gu, ' ').split(/\s+/).filter(Boolean);
const fast_route = words.length > 0 && words.length <= 6 && words.every((w) => GREET.has(w)) ? 'smalltalk' : '';

return {
  json: {
    update_id: msg.update_id,
    chat_id: msg.chat_id,
    user_text: msg.text,
    history_count: history.length,
    prompt,
    route_decision: fast_route,
    router_pass: fast_route ? 0 : null,
  },
};

// ⑥ Output. Reads ONLY $json: every branch sends the same CONTRACT
// { update_id, chat_id, route, output, tool_calls[], router{...}, faq{...}|null }.
const MAX_LEN = 4000; // Telegram max 4096 per message, keep a margin

const c = $json;
const raw = String(c.output ?? '').trim();
if (!raw) throw new Error(`Reply is empty (route: ${c.route})`);

// Words the prompts forbid but models sometimes still write: removed here for EVERY route (one place).
let reply = raw
  .replace(/\s*[،,]?\s*يا\s+(فندم|باشا|زميلي|سيدي)/g, '')
  .replace(/^[،,]\s*/, '')
  .replace(/سيادتك/g, 'حضرتك')
  .trim();
let truncated = false;
if (reply.length > MAX_LEN) {
  const cut = reply.slice(0, MAX_LEN);
  const lastBreak = Math.max(cut.lastIndexOf('\n'), cut.lastIndexOf('. '), cut.lastIndexOf(' '));
  reply = (lastBreak > MAX_LEN * 0.6 ? cut.slice(0, lastBreak) : cut).trim() + ' …';
  truncated = true;
}

const toolCalls = [...(c.tool_calls || [])];
if (c.router) toolCalls.push({ tool: 'router', input: null, output: { route: c.route, model: c.router.model, error: c.router.error, decided_by: c.router.decided_by } });

const escapeHtml = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    update_id: c.update_id,
    chat_id: c.chat_id,
    route: c.route,
    reply_text: reply,
    reply_html: escapeHtml(reply),
    truncated,
    tool_calls: toolCalls,
    router_log: { decided_by: c.router?.decided_by ?? 'unknown', model: c.router?.model ?? null, error: c.router?.error ?? null,
      faq_hit: c.faq ? c.faq.hit : null, faq_top_score: c.faq ? c.faq.top_score : null },
  },
};

// Greetings / thanks / goodbye (decided in code by the router): fixed reply, no model. Outputs the CONTRACT.
const ctx = $('Call Router').first().json;
const text = String(ctx.user_text || '');
const ar = /[\u0600-\u06FF]/.test(text) || !/[A-Za-z]/.test(text);
const has = (re) => re.test(text);
let output;
if (has(/(شكر|متشكر|تسلم|ميرسي|مرسي|يخليك|جزاك|thank|thx|\bty\b)/i)) output = ar ? 'العفو 😊 لو حضرتك احتجت أي حاجة تانية أنا هنا.' : "You're welcome 😊 I'm here if you need anything else.";
else if (has(/(السلامة|باي|bye|see you|later)/i)) output = ar ? 'مع السلامة 👋 لو حضرتك احتجت أي حاجة أنا موجود.' : "Goodbye 👋 I'm here whenever you need me.";
else output = ar
  ? 'أهلاً بحضرتك! 👋 أنا نور، مساعد الموارد البشرية في نيكسورا.\nأقدر أجاوب على أسئلة اللائحة، وأقولك رصيد إجازاتك وطلباتك وحضورك، وأقدملك طلب إجازة أو إذن، وأرد على أسئلة بوابة نيكسورا.\nحضرتك محتاج إيه؟'
  : "Hi! 👋 I'm Nour, the HR assistant at Nexora.\nI can answer policy questions, show your leave balance, requests and attendance, submit leave or permission requests, and help with the Nexora portal.\nWhat do you need?";
return { json: { update_id: ctx.update_id, chat_id: ctx.chat_id, route: 'smalltalk', output, tool_calls: [], router: ctx.router, faq: null } };

// The router could not tell the topic (even with the history): ask to clarify. Outputs the CONTRACT directly.
const ctx = $('Call Router').first().json;
const ar = /[\u0600-\u06FF]/.test(String(ctx.user_text || '')) ? true : $('Normalize Message').first().json.ui_lang === 'ar';
const output = ar
  ? 'معلش، ممكن حضرتك توضحلي السؤال أكتر؟ 🙏\nمثلاً: «رصيدي كام؟» أو «إجازة الجواز كام يوم؟» أو «إزاي أطلع شهادة خبرة؟»'
  : 'Sorry, could you tell me a bit more about what you need? 🙏\nFor example: "what is my leave balance?" or "how many days is marriage leave?"';
return { json: { update_id: ctx.update_id, chat_id: ctx.chat_id, route: 'unclear', output, tool_calls: [], router: ctx.router, faq: null } };

// Any failure: fixed apology instead of silence. Outputs the CONTRACT with the error logged.
const b = $('Build Prompt').first().json;
let ctx = null;
try { ctx = $('Call Router').first().json; } catch (e) { ctx = null; }
const t = String(b.user_text || '');
const ar = /[\u0600-\u06FF]/.test(t) || !/[A-Za-z]/.test(t);
let err = $json?.error?.message ?? $json?.error ?? null;
if (!err && $json?.route_decision === 'router_failed') err = $json.router?.error ?? 'router_failed';
if (!err) err = 'unknown_error';
err = typeof err === 'string' ? err : JSON.stringify(err).slice(0, 300);
const router = ctx?.router ?? { decided_by: 'none', model: null, error: err };
return [{ json: { update_id: b.update_id, chat_id: b.chat_id, route: 'router_error',
  output: ar ? 'معلش، عندي مشكلة مؤقتة دلوقتي 🙏 ممكن حضرتك تبعت رسالتك تاني بعد شوية؟' : "Sorry, I'm having a temporary problem right now 🙏 Could you send your message again in a little while?",
  tool_calls: [{ tool: 'error', input: { failed_after_route: ctx?.route_decision ?? null }, output: { error: err } }],
  router: { ...router, error: router.error ?? err }, faq: null } }];

// Linked employee: continue with the Build Prompt data, and tell the HR Agent who is talking
// (name + gender -> correct Arabic forms).
const b = $('Build Prompt').first().json;
const me = $json.me || {};
const who = `The employee: ${me.name ?? 'unknown'} (${me.gender ?? 'unknown'}).`;
// history goes to the sub-workflows (they cannot read nodes of this workflow)
let history = [];
try { history = $('Get Context').first().json.history || []; } catch (e) {}
return [{ json: { ...b, employee: me, history, prompt: b.prompt.replace('\n\nConversation so far', `\n${who}\n\nConversation so far`) } }];
